insert into private.quiz_catalog(slug,topic_id,questions) values
('red-cabbage-ph-indicator','acids-bases','[{"id":"q1","prompt":{"en":"What color does red cabbage anthocyanin indicator turn when added to a weakly alkaline baking soda (NaHCO₃, pH ~8.5) solution?","ky":"Кызыл кочандын антоцианин индикаторун аш содасынын (NaHCO₃, pH ~8.5) начар щелочтуу эритмесине кошкондо кандай өңгө өтөт?","ru":"Какую окраску принимает антоциановый индикатор при добавлении в слабощелочной раствор питьевой соды (NaHCO₃, pH ~8,5)?"},"options":[{"id":"a","text":{"en":"Bright ruby red","ky":"Ачык кызыл","ru":"Ярко-красную"},"isCorrect":false,"explanation":{"en":"Bright red appears in strongly acidic solutions (pH < 3) where the pigment is fully protonated.","ky":"Ачык кызыл өң күчтүү кислоталуу чөйрөдө (pH < 3) гана байкалат.","ru":"Ярко-красная окраска характерна для сильнокислой среды (pH < 3)."},"misconceptionTag":"acids-bases_concept_misinterpretation","misconceptionLabel":{"en":"Misinterpreting the mechanism in Red Cabbage pH Experiment","ky":"«Кызыл кочан pH-индикатору» тажрыйбасындагы кубулушту туура эмес чечмелөө","ru":"Неточная интерпретация механизма в опыте «Шкала pH из красной капусты»"}},{"id":"b","text":{"en":"Blue to teal-green","ky":"Көк же көгүш-жашыл","ru":"Синюю / сине-зелёную"},"isCorrect":true,"explanation":{"en":"Correct! At pH 8–9, deprotonation of the anthocyanin molecule shifts its absorption spectrum so it appears blue-green.","ky":"Туура! pH 8–9 чегинде антоцианин протонду берип, көк же көгүш-жашыл өңгө өтөт.","ru":"Верно! При pH 8–9 депротонированная форма антоциана окрашивает раствор в синий и сине-зелёный цвет."}},{"id":"c","text":{"en":"Colorless precipitate","ky":"Түссүз чөкмө","ru":"Бесцветный осадок"},"isCorrect":false,"explanation":{"en":"Anthocyanins remain dissolved in water and remain strongly colored across the pH range.","ky":"Антоцианиндер сууда эриген бойдон калат жана түссүз чөкмө бербейт.","ru":"Антоцианы остаются в растворе и сохраняют интенсивную окраску."},"misconceptionTag":"acids-bases_concept_misinterpretation","misconceptionLabel":{"en":"Misinterpreting the mechanism in Red Cabbage pH Experiment","ky":"«Кызыл кочан pH-индикатору» тажрыйбасындагы кубулушту туура эмес чечмелөө","ru":"Неточная интерпретация механизма в опыте «Шкала pH из красной капусты»"}}],"conceptTag":"acids-bases","hint":{"en":"Review the chemical equation (HIn (aq, red, pH < 3) ⇌ H⁺ (aq) + In⁻ (aq, blue/green, pH > 8)) and what you observed during the key reaction step.","ky":"Реакциянын теңдемесин (HIn (aq, red, pH < 3) ⇌ H⁺ (aq) + In⁻ (aq, blue/green, pH > 8)) жана тажрыйбанын негизги баскычындагы байкоону эстеңиз.","ru":"Вспомните уравнение процесса (HIn (aq, red, pH < 3) ⇌ H⁺ (aq) + In⁻ (aq, blue/green, pH > 8)) и наблюдения на ключевом этапе опыта."}},{"id":"q2","prompt":{"en":"Why can red cabbage extract distinguish more pH regions than phenolphthalein?","ky":"Эмне үчүн кызыл кочандын экстракты фенолфталеинге караганда pH шкаласынын көбүрөөк бөлүгүн айырмалай алат?","ru":"Почему экстракт краснокочанной капусты позволяет различить больше областей pH, чем фенолфталеин?"},"options":[{"id":"a","text":{"en":"It undergoes multiple reversible protonation equilibria, forming several distinctly colored molecular species.","ky":"Ал бир нече баскычтуу кайтарымдуу протон алмашууга кирип, ар кандай өңдөгү формаларды пайда кылат.","ru":"Он вступает в несколько ступеней протолитического равновесия, образуя ряд разноокрашенных форм."},"isCorrect":true,"explanation":{"en":"Exactly! Each protonation state has a different conjugated π-system and absorbs different wavelengths of visible light.","ky":"Эң туура! Ар бир баскычта молекуланын түзүлүшү өзгөрүп, жарыктын башка толкун узундугун жутат.","ru":"Точно! Каждая форма имеет разную систему сопряжённых связей и поглощает свет разной длины волны."}},{"id":"b","text":{"en":"It boils at a lower temperature than synthetic indicators.","ky":"Ал синтетикалык индикаторлорго караганда төмөн температурада кайнайт.","ru":"Он кипит при более низкой температуре, чем синтетические индикаторы."},"isCorrect":false,"explanation":{"en":"Boiling point does not determine acid–base color transitions in aqueous solution.","ky":"Кайноо температурасы индикатордун өңүнүн өзгөрүшүнө таасир этпейт.","ru":"Температура кипения не определяет кислотно-основные переходы окраски."},"misconceptionTag":"acids-bases_concept_misinterpretation","misconceptionLabel":{"en":"Misinterpreting the mechanism in Red Cabbage pH Experiment","ky":"«Кызыл кочан pH-индикатору» тажрыйбасындагы кубулушту туура эмес чечмелөө","ru":"Неточная интерпретация механизма в опыте «Шкала pH из красной капусты»"}}],"conceptTag":"acids-bases","hint":{"en":"Review the chemical equation (HIn (aq, red, pH < 3) ⇌ H⁺ (aq) + In⁻ (aq, blue/green, pH > 8)) and what you observed during the key reaction step.","ky":"Реакциянын теңдемесин (HIn (aq, red, pH < 3) ⇌ H⁺ (aq) + In⁻ (aq, blue/green, pH > 8)) жана тажрыйбанын негизги баскычындагы байкоону эстеңиз.","ru":"Вспомните уравнение процесса (HIn (aq, red, pH < 3) ⇌ H⁺ (aq) + In⁻ (aq, blue/green, pH > 8)) и наблюдения на ключевом этапе опыта."}}]'::jsonb),
('catalytic-decomposition-hydrogen-peroxide','reactions','[{"id":"q1","prompt":{"en":"What happens to the iodide ions (I⁻) after the decomposition of H₂O₂ is complete?","ky":"H₂O₂ ажырап бүткөндөн кийин иодид иондоруна (I⁻) эмне болот?","ru":"Что происходит с иодид-ионами (I⁻) после завершения разложения H₂O₂?"},"options":[{"id":"a","text":{"en":"They are regenerated in the second reaction step, remaining chemically unchanged overall (with minor side oxidation to I₂).","ky":"Алар экинчи баскычта кайра калыбына келет, б.а. катализатор катары сарпталбайт.","ru":"Они регенерируются на второй стадии механизма, выступая катализатором."},"isCorrect":true,"explanation":{"en":"Correct! A catalyst participates in the intermediate step (forming IO⁻) and is regenerated in the subsequent step.","ky":"Туура! Катализатор аралык реакцияга катышып (IO⁻ пайда кылат), кийинки баскычта кайра баштапкы абалына келет.","ru":"Верно! Катализатор образует промежуточный ион IO⁻ и полностью восстанавливается на втором шаге."}},{"id":"b","text":{"en":"They turn into oxygen gas molecules.","ky":"Алар кычкылтек газынын молекуласына айланат.","ru":"Они превращаются в молекулы газообразного кислорода."},"isCorrect":false,"explanation":{"en":"Elements cannot transmute in chemical reactions; all O₂ comes from the oxygen atoms in H₂O₂.","ky":"Химиялык реакцияда бир элемент экинчисине айланбайт; кычкылтек H₂O₂ молекуласынан гана чыгат.","ru":"В химических реакциях элементы не превращаются друг в друга; весь O₂ образуется из H₂O₂."},"misconceptionTag":"reactions_concept_misinterpretation","misconceptionLabel":{"en":"Misinterpreting the mechanism in Hydrogen Peroxide Catalysis","ky":"«Пероксиддин каталитикалык ажыроосу» тажрыйбасындагы кубулушту туура эмес чечмелөө","ru":"Неточная интерпретация механизма в опыте «Каталитическое разложение H₂O₂»"}}],"conceptTag":"reactions","hint":{"en":"Review the chemical equation (2H₂O₂ (aq) —[KI / MnO₂]→ 2H₂O (l) + O₂ (g) + ΔH) and what you observed during the key reaction step.","ky":"Реакциянын теңдемесин (2H₂O₂ (aq) —[KI / MnO₂]→ 2H₂O (l) + O₂ (g) + ΔH) жана тажрыйбанын негизги баскычындагы байкоону эстеңиз.","ru":"Вспомните уравнение процесса (2H₂O₂ (aq) —[KI / MnO₂]→ 2H₂O (l) + O₂ (g) + ΔH) и наблюдения на ключевом этапе опыта."}},{"id":"q2","prompt":{"en":"Why does visible steam rise from the foam column during this experiment?","ky":"Эмне үчүн бул тажрыйба учурунда көбүктөн буу көтөрүлөт?","ru":"Почему над столбом пены в этом опыте поднимается заметный пар?"},"options":[{"id":"a","text":{"en":"The decomposition of H₂O₂ into H₂O and O₂ is strongly exothermic (ΔH = −196 kJ per 2 mol H₂O₂), heating the water into vapor.","ky":"H₂O₂ ажыроосу экзотермиялык реакция болгондуктан (ΔH < 0), бөлүнүп чыккан жылуулук сууну буулантат.","ru":"Разложение H₂O₂ сильно экзотермично (ΔH < 0), и выделяющаяся теплота испаряет часть воды."},"isCorrect":true,"explanation":{"en":"Spot on! Breaking the weak O–O peroxide bond and forming stronger O=O and O–H bonds releases significant thermal energy.","ky":"Эң туура! Алсыз пероксиддик байланыш үзүлүп, бекем байланыштар түзүлгөндө көп жылуулук бөлүнүп чыгат.","ru":"Именно так! Образование более прочных связей в H₂O и O₂ сопровождается выделением большого количества теплоты."}},{"id":"b","text":{"en":"Dish soap reacts endothermically with glass.","ky":"Суюк самын айнек менен эндотермиялык реакцияга кирет.","ru":"Мыло вступает в эндотермическую реакцию со стеклом."},"isCorrect":false,"explanation":{"en":"Soap only acts physically as a surfactant to trap the O₂ bubbles; the heat comes from H₂O₂ decomposition.","ky":"Самын газ көбүкчөлөрүн гана кармап калат, ал эми жылуулук пероксиддин ажыроосунан чыгат.","ru":"Мыло лишь физически удерживает пузырьки кислорода."},"misconceptionTag":"reactions_concept_misinterpretation","misconceptionLabel":{"en":"Misinterpreting the mechanism in Hydrogen Peroxide Catalysis","ky":"«Пероксиддин каталитикалык ажыроосу» тажрыйбасындагы кубулушту туура эмес чечмелөө","ru":"Неточная интерпретация механизма в опыте «Каталитическое разложение H₂O₂»"}}],"conceptTag":"reactions","hint":{"en":"Review the chemical equation (2H₂O₂ (aq) —[KI / MnO₂]→ 2H₂O (l) + O₂ (g) + ΔH) and what you observed during the key reaction step.","ky":"Реакциянын теңдемесин (2H₂O₂ (aq) —[KI / MnO₂]→ 2H₂O (l) + O₂ (g) + ΔH) жана тажрыйбанын негизги баскычындагы байкоону эстеңиз.","ru":"Вспомните уравнение процесса (2H₂O₂ (aq) —[KI / MnO₂]→ 2H₂O (l) + O₂ (g) + ΔH) и наблюдения на ключевом этапе опыта."}}]'::jsonb),
('electrolysis-of-water-hoffman','electrochemistry','[{"id":"q1","prompt":{"en":"If 18 mL of oxygen gas (O₂) collects above the anode during water electrolysis, what volume of hydrogen gas (H₂) should collect above the cathode at the same temperature and pressure?","ky":"Эгерде суунун электролизинде аноддо 18 мл кычкылтек (O₂) чогулса, ошол эле шартта катоддо канча көлөмдөгү суутек (H₂) чогулат?","ru":"Если над анодом при электролизе воды собралось 18 мл кислорода (O₂), какой объём водорода (H₂) соберётся над катодом при тех же условиях?"},"options":[{"id":"a","text":{"en":"9 mL","ky":"9 мл","ru":"9 мл"},"isCorrect":false,"explanation":{"en":"Remember that water is H₂O — there are 2 hydrogen atoms for every 1 oxygen atom, so hydrogen volume is double, not half.","ky":"Суунун формуласы H₂O болгондуктан, суутектин көлөмү эки эсе аз эмес, эки эсе көп болот.","ru":"В формуле H₂O на 1 атом кислорода приходится 2 атома водорода, поэтому объём водорода вдвое больше, а не меньше."},"misconceptionTag":"electrochemistry_concept_misinterpretation","misconceptionLabel":{"en":"Misinterpreting the mechanism in Electrolysis of Water","ky":"«Суунун электролизи» тажрыйбасындагы кубулушту туура эмес чечмелөө","ru":"Неточная интерпретация механизма в опыте «Электролиз воды»"}},{"id":"b","text":{"en":"36 mL","ky":"36 мл","ru":"36 мл"},"isCorrect":true,"explanation":{"en":"Correct! By 2H₂O → 2H₂ + O₂, the mole and volume ratio V(H₂):V(O₂) is 2:1, so 2 × 18 mL = 36 mL.","ky":"Туура! 2H₂O → 2H₂ + O₂ теңдемеси боюнча V(H₂):V(O₂) = 2:1, демек 2 × 18 мл = 36 мл.","ru":"Верно! По уравнению 2H₂O → 2H₂ + O₂ соотношение объёмов V(H₂):V(O₂) = 2:1, значит 2 × 18 мл = 36 мл."}},{"id":"c","text":{"en":"18 mL","ky":"18 мл","ru":"18 мл"},"isCorrect":false,"explanation":{"en":"Equal volumes would only occur if the stoichiometric ratio were 1:1.","ky":"Көлөмдөр 1:1 катышында болгондо гана бирдей болмок.","ru":"Равные объёмы выделялись бы только при стехиометрическом соотношении 1:1."},"misconceptionTag":"electrochemistry_concept_misinterpretation","misconceptionLabel":{"en":"Misinterpreting the mechanism in Electrolysis of Water","ky":"«Суунун электролизи» тажрыйбасындагы кубулушту туура эмес чечмелөө","ru":"Неточная интерпретация механизма в опыте «Электролиз воды»"}}],"conceptTag":"electrochemistry","hint":{"en":"Review the chemical equation (2H₂O (l) —[DC current, Na₂SO₄]→ 2H₂ (g, cathode) + O₂ (g, anode)) and what you observed during the key reaction step.","ky":"Реакциянын теңдемесин (2H₂O (l) —[DC current, Na₂SO₄]→ 2H₂ (g, cathode) + O₂ (g, anode)) жана тажрыйбанын негизги баскычындагы байкоону эстеңиз.","ru":"Вспомните уравнение процесса (2H₂O (l) —[DC current, Na₂SO₄]→ 2H₂ (g, cathode) + O₂ (g, anode)) и наблюдения на ключевом этапе опыта."}}]'::jsonb),
('iron-nail-copper-sulfate-displacement','metals','[{"id":"q1","prompt":{"en":"What would you observe if a strip of copper metal (Cu) were placed into a solution of iron(II) sulfate (FeSO₄)?","ky":"Эгерде жез пластинкасын (Cu) темир(II) сульфатынын (FeSO₄) эритмесине салсак эмне байкалат?","ru":"Что произойдёт, если опустить медную пластинку (Cu) в раствор сульфата железа(II) FeSO₄?"},"options":[{"id":"a","text":{"en":"No reaction occurs because copper is less reactive than iron and cannot reduce Fe²⁺ ions.","ky":"Реакция жүрбөйт, анткени жез темирге караганда пассивдүү жана Fe²⁺ иондорун сүрүп чыгара албайт.","ru":"Реакция не пойдёт, так как медь менее активна, чем железо, и не может восстановить ионы Fe²⁺."},"isCorrect":true,"explanation":{"en":"Correct! A less reactive metal cannot displace a more reactive metal from its salt solution.","ky":"Туура! Активдүүлүгү төмөн металл өзүнөн активдүү металлды тузунун эритмесинен сүрүп чыгара албайт.","ru":"Верно! Менее активный металл не вытесняет более активный из раствора его соли."}},{"id":"b","text":{"en":"Grey iron metal immediately plates onto the copper strip.","ky":"Жез пластинканын бетине дароо боз темир чөгөт.","ru":"На медной пластинке сразу выделится слой серого железа."},"isCorrect":false,"explanation":{"en":"The reverse reaction has a negative cell potential (ΔE° = −0.78 V) and is non-spontaneous.","ky":"Тескери реакция өз алдынча жүрбөйт (ΔE° = −0.78 В).","ru":"Обратная реакция термодинамически невозможна без внешнего источника тока."},"misconceptionTag":"metals_concept_misinterpretation","misconceptionLabel":{"en":"Misinterpreting the mechanism in Iron Nail in Copper Sulfate","ky":"«Темир мык жана жез сульфаты» тажрыйбасындагы кубулушту туура эмес чечмелөө","ru":"Неточная интерпретация механизма в опыте «Железный гвоздь в сульфате меди»"}}],"conceptTag":"metals","hint":{"en":"Review the chemical equation (Fe (s) + CuSO₄ (aq, blue) → FeSO₄ (aq, pale green) + Cu (s, salmon-red)) and what you observed during the key reaction step.","ky":"Реакциянын теңдемесин (Fe (s) + CuSO₄ (aq, blue) → FeSO₄ (aq, pale green) + Cu (s, salmon-red)) жана тажрыйбанын негизги баскычындагы байкоону эстеңиз.","ru":"Вспомните уравнение процесса (Fe (s) + CuSO₄ (aq, blue) → FeSO₄ (aq, pale green) + Cu (s, salmon-red)) и наблюдения на ключевом этапе опыта."}}]'::jsonb),
('flame-tests-metal-cations','energy','[{"id":"q1","prompt":{"en":"An unknown white chloride salt produces a vivid emerald blue-green flame in a Bunsen burner. Which metal cation is present?","ky":"Белгисиз ак туз Бунзен жалынында ачык көгүш-жашыл өң менен күйөт. Анын курамында кайсы металлдын катиону бар?","ru":"Неизвестная соль окрашивает пламя горелки в яркий изумрудно-зелёный цвет. Какой катион металла присутствует в пробе?"},"options":[{"id":"a","text":{"en":"Sodium (Na⁺)","ky":"Натрий (Na⁺)","ru":"Натрий (Na⁺)"},"isCorrect":false,"explanation":{"en":"Sodium produces an intense golden-yellow flame (589 nm), not blue-green.","ky":"Натрий иондору жалынды ачык сары өңгө боёйт (589 нм).","ru":"Ионы натрия окрашивают пламя в интенсивный жёлтый цвет (589 нм)."},"misconceptionTag":"energy_concept_misinterpretation","misconceptionLabel":{"en":"Misinterpreting the mechanism in Flame Colors of Metals","ky":"«Металлдардын жалынынын өңү» тажрыйбасындагы кубулушту туура эмес чечмелөө","ru":"Неточная интерпретация механизма в опыте «Окрашивание пламени металлами»"}},{"id":"b","text":{"en":"Copper (Cu²⁺)","ky":"Жез (Cu²⁺)","ru":"Медь (Cu²⁺)"},"isCorrect":true,"explanation":{"en":"Correct! Copper(II) halides emit characteristic blue-green light when heated in a flame.","ky":"Туура! Жез(II) туздары жалынды зумруд сымал көгүш-жашыл өңгө боёйт.","ru":"Верно! Галогениды меди(II) окрашивают пламя в характерный сине-зелёный цвет."}}],"conceptTag":"energy","hint":{"en":"Review the chemical equation (M⁺ (ground state) + thermal energy → M⁺* (excited) → M⁺ + hν (characteristic photon)) and what you observed during the key reaction step.","ky":"Реакциянын теңдемесин (M⁺ (ground state) + thermal energy → M⁺* (excited) → M⁺ + hν (characteristic photon)) жана тажрыйбанын негизги баскычындагы байкоону эстеңиз.","ru":"Вспомните уравнение процесса (M⁺ (ground state) + thermal energy → M⁺* (excited) → M⁺ + hν (characteristic photon)) и наблюдения на ключевом этапе опыта."}}]'::jsonb),
('paper-chromatography-plant-ink-pigments','separation','[{"id":"q1","prompt":{"en":"Why must the starting line on a chromatography strip be drawn with a graphite pencil instead of a ballpoint pen?","ky":"Эмне үчүн хроматография кагазындагы баштапкы сызыкты ручка менен эмес, жөнөкөй карандаш менен чийүү керек?","ru":"Почему стартовую линию на хроматографической бумаге проводят графитовым карандашом, а не ручкой?"},"options":[{"id":"a","text":{"en":"Graphite is insoluble in the mobile phase, whereas pen ink would dissolve and travel up the paper, contaminating the sample bands.","ky":"Графит эриткичте эрибейт, ал эми ручканын сыясы эрип кетип, тажрыйбанын жыйынтыгын бузат.","ru":"Графит нерастворим в элюенте, тогда как чернила ручки растворятся и смешаются с исследуемыми пигментами."},"isCorrect":true,"explanation":{"en":"Correct! Using pen ink on the baseline would introduce extra dyes that elute alongside your sample.","ky":"Туура! Ручканын сыясы өзү да бир нече боёктон тургандыктан, үлгү менен аралашып кетет.","ru":"Верно! Чернила ручки сами состоят из смеси красителей и исказят хроматограмму."}},{"id":"b","text":{"en":"Graphite acts as a catalyst that speeds up capillary action.","ky":"Графит капиллярдык кыймылды тездетүүчү катализатор болуп саналат.","ru":"Графит служит катализатором, ускоряющим подъём воды."},"isCorrect":false,"explanation":{"en":"Graphite is chemically inert here; it is simply an insoluble marker.","ky":"Графит бул жерде эч кандай реакцияга кирбейт, болгону эрибеген белги катары кызмат кылат.","ru":"Графит химически инертен и служит только нерастворимой меткой."},"misconceptionTag":"separation_concept_misinterpretation","misconceptionLabel":{"en":"Misinterpreting the mechanism in Paper Chromatography","ky":"«Кагаз хроматографиясы» тажрыйбасындагы кубулушту туура эмес чечмелөө","ru":"Неточная интерпретация механизма в опыте «Бумажная хроматография»"}}],"conceptTag":"separation","hint":{"en":"Review the chemical equation (Rf = (distance traveled by pigment) / (distance traveled by solvent front)) and what you observed during the key reaction step.","ky":"Реакциянын теңдемесин (Rf = (distance traveled by pigment) / (distance traveled by solvent front)) жана тажрыйбанын негизги баскычындагы байкоону эстеңиз.","ru":"Вспомните уравнение процесса (Rf = (distance traveled by pigment) / (distance traveled by solvent front)) и наблюдения на ключевом этапе опыта."}}]'::jsonb),
('acid-base-titration-phenolphthalein','acids-bases','[{"id":"q1","conceptTag":"acids-bases","hint":{"en":"Focus on the reactants and products shown in the balanced equation for Acids & Bases.","ky":"«Кислоталар жана негиздер» темасындагы реакциянын баштапкы заттарына жана продуктыларына көңүл буруңуз.","ru":"Обратите внимание на исходные вещества и продукты в уравнении реакции по теме «Кислоты и основания»."},"prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Acid–Base Neutralization & Phenolphthalein Endpoint\"?","ky":"«Кислота менен негиздин нейтралдашуусу (фенолфталеин менен титрлөө)» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Реакция нейтрализации и титрование с фенолфталеином»?"},"options":[{"id":"a","text":{"en":"HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l)","ky":"HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l)","ru":"HCl (aq) + NaOH (aq) → NaCl (aq) + H₂O (l)"},"isCorrect":true,"explanation":{"en":"Correct! This balanced representation accounts for the observed macroscopic change in the experiment.","ky":"Туура! Бул теңдеме тажрыйбада байкалган өзгөрүүнү так сүрөттөйт.","ru":"Верно! Эта схема точно описывает наблюдаемые в опыте изменения."}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."},"isCorrect":false,"misconceptionTag":"ignoring_macroscopic_reaction_evidence","misconceptionLabel":{"en":"Overlooking visible evidence of chemical or phase change","ky":"Химиялык же фазалык өзгөрүүнүн визуалдык белгилерин эске албоо","ru":"Игнорирование видимых признаков химического или фазового превращения"},"explanation":{"en":"Look closely at the video observation — a clear measurable change occurs during the procedure.","ky":"Видеого көңүл буруңуз — тажрыйба учурунда даана байкалган өзгөрүү жүрөт.","ru":"Обратите внимание на видео — в ходе опыта наблюдается отчётливый признак процесса."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."},"isCorrect":false,"misconceptionTag":"conservation_of_mass_violation","misconceptionLabel":{"en":"Misunderstanding conservation of mass and atoms in chemical reactions","ky":"Заттын массасынын жана атомдордун сакталуу мыйзамын туура эмес түшүнүү","ru":"Нарушение закона сохранения массы и числа атомов в химических реакциях"},"explanation":{"en":"By the Law of Conservation of Mass, atoms are rearranged—never destroyed—in chemical reactions.","ky":"Массанын сакталуу мыйзамы боюнча химиялык реакцияда атомдор жоголбойт, кайра топтошот.","ru":"Согласно закону сохранения массы, атомы в химических реакциях перегруппировываются, но не исчезают."}}]},{"id":"q2","conceptTag":"acids-bases","hint":{"en":"Consider what visible macroscopic evidence confirms that the process has taken place.","ky":"Тажрыйбанын жүргөнүн кайсы негизги визуалдык белги далилдей турганын эстеңиз.","ru":"Подумайте, какой наглядный признак подтверждает протекание данного опыта."},"prompt":{"en":"What is the key observable outcome verified in \"Acid–Base Neutralization & Phenolphthalein Endpoint\"?","ky":"«Кислота менен негиздин нейтралдашуусу (фенолфталеин менен титрлөө)» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Реакция нейтрализации и титрование с фенолфталеином»?"},"options":[{"id":"a","text":{"en":"Deliver NaOH drop-by-drop from a burette to catch the exact equivalence point where colorless solution turns faint pink.","ky":"Бюреткадан NaOH тамчылатып кошуп, түссүз эритме мала кызыл өңгө өткөн эквиваленттик чекитти табыңыз.","ru":"Добавляйте NaOH по каплям из бюретки до появления устойчивой бледно-малиновой окраски фенолфталеина."},"isCorrect":true,"explanation":{"en":"Spot on! This macroscopic observation directly reflects the underlying molecular mechanism.","ky":"Эң туура! Бул байкоо молекулярдык деңгээлдеги процессти түздөн-түз чагылдырат.","ru":"Точно! Это макроскопическое наблюдение напрямую отражает молекулярный механизм процесса."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."},"isCorrect":false,"misconceptionTag":"inert_apparatus_confusion","misconceptionLabel":{"en":"Confusing inert borosilicate glassware with active chemical reactants","ky":"Инерттүү лабораториялык идишти активдүү реактив менен алмаштыруу","ru":"Смешение роли инертной химической посуды и реагирующих веществ"},"explanation":{"en":"Borosilicate laboratory glassware is chemically inert under these conditions; only the reagents inside react.","ky":"Лабораториялык боросиликат айнеги бул шарттарда химиялык жактан инерттүү болот.","ru":"Лабораторная посуда из боросиликатного стекла химически инертна в условиях данного опыта."}}]}]'::jsonb),
('universal-indicator-ph-column','acids-bases','[{"id":"q1","conceptTag":"acids-bases","hint":{"en":"Focus on the reactants and products shown in the balanced equation for Acids & Bases.","ky":"«Кислоталар жана негиздер» темасындагы реакциянын баштапкы заттарына жана продуктыларына көңүл буруңуз.","ru":"Обратите внимание на исходные вещества и продукты в уравнении реакции по теме «Кислоты и основания»."},"prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Density & pH Rainbow Column in a Graduated Cylinder\"?","ky":"«Цилиндрдеги тыгыздык жана универсалдуу индикатордун pH-санжырасы» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Радужная колонка pH с универсальным индикатором»?"},"options":[{"id":"a","text":{"en":"CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12)","ky":"CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12)","ru":"CO₃²⁻ (aq, bottom) + H⁺ (aq, top) → continuous pH gradient (pH 2 → 12)"},"isCorrect":true,"explanation":{"en":"Correct! This balanced representation accounts for the observed macroscopic change in the experiment.","ky":"Туура! Бул теңдеме тажрыйбада байкалган өзгөрүүнү так сүрөттөйт.","ru":"Верно! Эта схема точно описывает наблюдаемые в опыте изменения."}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."},"isCorrect":false,"misconceptionTag":"ignoring_macroscopic_reaction_evidence","misconceptionLabel":{"en":"Overlooking visible evidence of chemical or phase change","ky":"Химиялык же фазалык өзгөрүүнүн визуалдык белгилерин эске албоо","ru":"Игнорирование видимых признаков химического или фазового превращения"},"explanation":{"en":"Look closely at the video observation — a clear measurable change occurs during the procedure.","ky":"Видеого көңүл буруңуз — тажрыйба учурунда даана байкалган өзгөрүү жүрөт.","ru":"Обратите внимание на видео — в ходе опыта наблюдается отчётливый признак процесса."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."},"isCorrect":false,"misconceptionTag":"conservation_of_mass_violation","misconceptionLabel":{"en":"Misunderstanding conservation of mass and atoms in chemical reactions","ky":"Заттын массасынын жана атомдордун сакталуу мыйзамын туура эмес түшүнүү","ru":"Нарушение закона сохранения массы и числа атомов в химических реакциях"},"explanation":{"en":"By the Law of Conservation of Mass, atoms are rearranged—never destroyed—in chemical reactions.","ky":"Массанын сакталуу мыйзамы боюнча химиялык реакцияда атомдор жоголбойт, кайра топтошот.","ru":"Согласно закону сохранения массы, атомы в химических реакциях перегруппировываются, но не исчезают."}}]},{"id":"q2","conceptTag":"acids-bases","hint":{"en":"Consider what visible macroscopic evidence confirms that the process has taken place.","ky":"Тажрыйбанын жүргөнүн кайсы негизги визуалдык белги далилдей турганын эстеңиз.","ru":"Подумайте, какой наглядный признак подтверждает протекание данного опыта."},"prompt":{"en":"What is the key observable outcome verified in \"Density & pH Rainbow Column in a Graduated Cylinder\"?","ky":"«Цилиндрдеги тыгыздык жана универсалдуу индикатордун pH-санжырасы» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Радужная колонка pH с универсальным индикатором»?"},"options":[{"id":"a","text":{"en":"Create a vertical density gradient from dense sodium carbonate at the bottom to dilute acid at the top, displaying the full pH spectrum.","ky":"Түбүндө тыгыз сода эритмеси, үстүндө кислота жайгашкан вертикалдуу спектр түзүңүз.","ru":"Создайте градиент плотности и pH в высоком цилиндре от красного наверху до фиолетового внизу."},"isCorrect":true,"explanation":{"en":"Spot on! This macroscopic observation directly reflects the underlying molecular mechanism.","ky":"Эң туура! Бул байкоо молекулярдык деңгээлдеги процессти түздөн-түз чагылдырат.","ru":"Точно! Это макроскопическое наблюдение напрямую отражает молекулярный механизм процесса."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."},"isCorrect":false,"misconceptionTag":"inert_apparatus_confusion","misconceptionLabel":{"en":"Confusing inert borosilicate glassware with active chemical reactants","ky":"Инерттүү лабораториялык идишти активдүү реактив менен алмаштыруу","ru":"Смешение роли инертной химической посуды и реагирующих веществ"},"explanation":{"en":"Borosilicate laboratory glassware is chemically inert under these conditions; only the reagents inside react.","ky":"Лабораториялык боросиликат айнеги бул шарттарда химиялык жактан инерттүү болот.","ru":"Лабораторная посуда из боросиликатного стекла химически инертна в условиях данного опыта."}}]}]'::jsonb),
('iodine-clock-reaction-kinetics','reactions','[{"id":"q1","conceptTag":"reactions","hint":{"en":"Focus on the reactants and products shown in the balanced equation for Chemical Reactions.","ky":"«Химиялык реакциялар» темасындагы реакциянын баштапкы заттарына жана продуктыларына көңүл буруңуз.","ru":"Обратите внимание на исходные вещества и продукты в уравнении реакции по теме «Химические реакции»."},"prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"The Iodine Clock Reaction: Visualizing Reaction Rates\"?","ky":"«Йод сааты реакциясы: Химиялык ылдамдыкты визуалдык байкоо» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Йодные часы: наглядная кинетика химических реакций»?"},"options":[{"id":"a","text":{"en":"IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue)","ky":"IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue)","ru":"IO₃⁻ + 3HSO₃⁻ → I⁻ + 3SO₄²⁻ + 3H⁺  →  I₂ + starch (sudden dark blue)"},"isCorrect":true,"explanation":{"en":"Correct! This balanced representation accounts for the observed macroscopic change in the experiment.","ky":"Туура! Бул теңдеме тажрыйбада байкалган өзгөрүүнү так сүрөттөйт.","ru":"Верно! Эта схема точно описывает наблюдаемые в опыте изменения."}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."},"isCorrect":false,"misconceptionTag":"ignoring_macroscopic_reaction_evidence","misconceptionLabel":{"en":"Overlooking visible evidence of chemical or phase change","ky":"Химиялык же фазалык өзгөрүүнүн визуалдык белгилерин эске албоо","ru":"Игнорирование видимых признаков химического или фазового превращения"},"explanation":{"en":"Look closely at the video observation — a clear measurable change occurs during the procedure.","ky":"Видеого көңүл буруңуз — тажрыйба учурунда даана байкалган өзгөрүү жүрөт.","ru":"Обратите внимание на видео — в ходе опыта наблюдается отчётливый признак процесса."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."},"isCorrect":false,"misconceptionTag":"conservation_of_mass_violation","misconceptionLabel":{"en":"Misunderstanding conservation of mass and atoms in chemical reactions","ky":"Заттын массасынын жана атомдордун сакталуу мыйзамын туура эмес түшүнүү","ru":"Нарушение закона сохранения массы и числа атомов в химических реакциях"},"explanation":{"en":"By the Law of Conservation of Mass, atoms are rearranged—never destroyed—in chemical reactions.","ky":"Массанын сакталуу мыйзамы боюнча химиялык реакцияда атомдор жоголбойт, кайра топтошот.","ru":"Согласно закону сохранения массы, атомы в химических реакциях перегруппировываются, но не исчезают."}}]},{"id":"q2","conceptTag":"reactions","hint":{"en":"Consider what visible macroscopic evidence confirms that the process has taken place.","ky":"Тажрыйбанын жүргөнүн кайсы негизги визуалдык белги далилдей турганын эстеңиз.","ru":"Подумайте, какой наглядный признак подтверждает протекание данного опыта."},"prompt":{"en":"What is the key observable outcome verified in \"The Iodine Clock Reaction: Visualizing Reaction Rates\"?","ky":"«Йод сааты реакциясы: Химиялык ылдамдыкты визуалдык байкоо» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Йодные часы: наглядная кинетика химических реакций»?"},"options":[{"id":"a","text":{"en":"Mix two colorless liquids and time how concentration and temperature control the sudden flash to deep blue-black starch-iodine complex.","ky":"Эки түссүз эритмени кошуп, концентрация менен температура кочкул көк өңдүн пайда болуу убактысына кантип таасир этерин ченеңиз.","ru":"Измерьте время до внезапного посинения раствора при разных концентрациях реагентов и температурах."},"isCorrect":true,"explanation":{"en":"Spot on! This macroscopic observation directly reflects the underlying molecular mechanism.","ky":"Эң туура! Бул байкоо молекулярдык деңгээлдеги процессти түздөн-түз чагылдырат.","ru":"Точно! Это макроскопическое наблюдение напрямую отражает молекулярный механизм процесса."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."},"isCorrect":false,"misconceptionTag":"inert_apparatus_confusion","misconceptionLabel":{"en":"Confusing inert borosilicate glassware with active chemical reactants","ky":"Инерттүү лабораториялык идишти активдүү реактив менен алмаштыруу","ru":"Смешение роли инертной химической посуды и реагирующих веществ"},"explanation":{"en":"Borosilicate laboratory glassware is chemically inert under these conditions; only the reagents inside react.","ky":"Лабораториялык боросиликат айнеги бул шарттарда химиялык жактан инерттүү болот.","ru":"Лабораторная посуда из боросиликатного стекла химически инертна в условиях данного опыта."}}]}]'::jsonb),
('golden-rain-lead-iodide-precipitation','reactions','[{"id":"q1","conceptTag":"reactions","hint":{"en":"Focus on the reactants and products shown in the balanced equation for Chemical Reactions.","ky":"«Химиялык реакциялар» темасындагы реакциянын баштапкы заттарына жана продуктыларына көңүл буруңуз.","ru":"Обратите внимание на исходные вещества и продукты в уравнении реакции по теме «Химические реакции»."},"prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Golden Rain: Recrystallization of Lead(II) Iodide\"?","ky":"««Алтын жамгыр»: Коргошун(II) иодидинин чөгүшү жана кристаллдашуусу» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте ««Золотой дождь»: осаждение и перекристаллизация иодида свинца(II)»?"},"options":[{"id":"a","text":{"en":"Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq)","ky":"Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq)","ru":"Pb(NO₃)₂ (aq) + 2KI (aq) → PbI₂ (s, shimmering gold crystals)↓ + 2KNO₃ (aq)"},"isCorrect":true,"explanation":{"en":"Correct! This balanced representation accounts for the observed macroscopic change in the experiment.","ky":"Туура! Бул теңдеме тажрыйбада байкалган өзгөрүүнү так сүрөттөйт.","ru":"Верно! Эта схема точно описывает наблюдаемые в опыте изменения."}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."},"isCorrect":false,"misconceptionTag":"ignoring_macroscopic_reaction_evidence","misconceptionLabel":{"en":"Overlooking visible evidence of chemical or phase change","ky":"Химиялык же фазалык өзгөрүүнүн визуалдык белгилерин эске албоо","ru":"Игнорирование видимых признаков химического или фазового превращения"},"explanation":{"en":"Look closely at the video observation — a clear measurable change occurs during the procedure.","ky":"Видеого көңүл буруңуз — тажрыйба учурунда даана байкалган өзгөрүү жүрөт.","ru":"Обратите внимание на видео — в ходе опыта наблюдается отчётливый признак процесса."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."},"isCorrect":false,"misconceptionTag":"conservation_of_mass_violation","misconceptionLabel":{"en":"Misunderstanding conservation of mass and atoms in chemical reactions","ky":"Заттын массасынын жана атомдордун сакталуу мыйзамын туура эмес түшүнүү","ru":"Нарушение закона сохранения массы и числа атомов в химических реакциях"},"explanation":{"en":"By the Law of Conservation of Mass, atoms are rearranged—never destroyed—in chemical reactions.","ky":"Массанын сакталуу мыйзамы боюнча химиялык реакцияда атомдор жоголбойт, кайра топтошот.","ru":"Согласно закону сохранения массы, атомы в химических реакциях перегруппировываются, но не исчезают."}}]},{"id":"q2","conceptTag":"reactions","hint":{"en":"Consider what visible macroscopic evidence confirms that the process has taken place.","ky":"Тажрыйбанын жүргөнүн кайсы негизги визуалдык белги далилдей турганын эстеңиз.","ru":"Подумайте, какой наглядный признак подтверждает протекание данного опыта."},"prompt":{"en":"What is the key observable outcome verified in \"Golden Rain: Recrystallization of Lead(II) Iodide\"?","ky":"««Алтын жамгыр»: Коргошун(II) иодидинин чөгүшү жана кристаллдашуусу» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте ««Золотой дождь»: осаждение и перекристаллизация иодида свинца(II)»?"},"options":[{"id":"a","text":{"en":"Dissolve yellow PbI₂ precipitate in hot water and watch hexagonal golden crystal platelets snow down as the solution cools