('daniel-galvanic-cell-copper-zinc-lemon','electrochemistry','[{"id":"q1","conceptTag":"electrochemistry","hint":{"en":"Focus on the reactants and products shown in the balanced equation for Electrochemistry.","ky":"«Электрохимия» темасындагы реакциянын баштапкы заттарына жана продуктыларына көңүл буруңуз.","ru":"Обратите внимание на исходные вещества и продукты в уравнении реакции по теме «Электрохимия»."},"prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Building a Zinc–Copper Galvanic Cell & Fruit Battery\"?","ky":"«Цинк–жез гальваникалык элементи жана жемиш батареясы» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Гальванический элемент Якоби–Даниэля (Zn–Cu) и фруктовая батарейка»?"},"options":[{"id":"a","text":{"en":"Zn (s) + Cu²⁺ (aq) → Zn²⁺ (aq) + Cu (s)   (E°_cell = +1.10 V)","ky":"Zn (s) + Cu²⁺ (aq) → Zn²⁺ (aq) + Cu (s)   (E°_cell = +1.10 V)","ru":"Zn (s) + Cu²⁺ (aq) → Zn²⁺ (aq) + Cu (s)   (E°_cell = +1.10 V)"},"isCorrect":true,"explanation":{"en":"Correct! This balanced representation accounts for the observed macroscopic change in the experiment.","ky":"Туура! Бул теңдеме тажрыйбада байкалган өзгөрүүнү так сүрөттөйт.","ru":"Верно! Эта схема точно описывает наблюдаемые в опыте изменения."}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."},"isCorrect":false,"misconceptionTag":"ignoring_macroscopic_reaction_evidence","misconceptionLabel":{"en":"Overlooking visible evidence of chemical or phase change","ky":"Химиялык же фазалык өзгөрүүнүн визуалдык белгилерин эске албоо","ru":"Игнорирование видимых признаков химического или фазового превращения"},"explanation":{"en":"Look closely at the video observation — a clear measurable change occurs during the procedure.","ky":"Видеого көңүл буруңуз — тажрыйба учурунда даана байкалган өзгөрүү жүрөт.","ru":"Обратите внимание на видео — в ходе опыта наблюдается отчётливый признак процесса."}},{"id":"c","text":{"en":"Mass is destroyed during the reaction so the total number of atoms decreases.","ky":"Реакция учурунда заттын массасы жоголуп, атомдордун жалпы саны азаят.","ru":"В ходе реакции часть атомов исчезает, нарушая закон сохранения массы."},"isCorrect":false,"misconceptionTag":"conservation_of_mass_violation","misconceptionLabel":{"en":"Misunderstanding conservation of mass and atoms in chemical reactions","ky":"Заттын массасынын жана атомдордун сакталуу мыйзамын туура эмес түшүнүү","ru":"Нарушение закона сохранения массы и числа атомов в химических реакциях"},"explanation":{"en":"By the Law of Conservation of Mass, atoms are rearranged—never destroyed—in chemical reactions.","ky":"Массанын сакталуу мыйзамы боюнча химиялык реакцияда атомдор жоголбойт, кайра топтошот.","ru":"Согласно закону сохранения массы, атомы в химических реакциях перегруппировываются, но не исчезают."}}]},{"id":"q2","conceptTag":"electrochemistry","hint":{"en":"Consider what visible macroscopic evidence confirms that the process has taken place.","ky":"Тажрыйбанын жүргөнүн кайсы негизги визуалдык белги далилдей турганын эстеңиз.","ru":"Подумайте, какой наглядный признак подтверждает протекание данного опыта."},"prompt":{"en":"What is the key observable outcome verified in \"Building a Zinc–Copper Galvanic Cell & Fruit Battery\"?","ky":"«Цинк–жез гальваникалык элементи жана жемиш батареясы» тажрыйбасында кайсы негизги кубулуш байкалат?","ru":"Какой ключевой наглядный результат подтверждается в опыте «Гальванический элемент Якоби–Даниэля (Zn–Cu) и фруктовая батарейка»?"},"options":[{"id":"a","text":{"en":"Convert spontaneous redox electron transfer between zinc and copper electrodes into measurable electrical voltage that lights an LED.","ky":"Цинк менен жез электроддорунун ортосундагы электрондордун агымын электр тогуна айландырып, вольтметр жана светодиод менен текшериңиз.","ru":"Превратите химическую энергию окислительно-восстановительной реакции между цинком и медью в электрическое напряжение 1,10 В."},"isCorrect":true,"explanation":{"en":"Spot on! This macroscopic observation directly reflects the underlying molecular mechanism.","ky":"Эң туура! Бул байкоо молекулярдык деңгээлдеги процессти түздөн-түз чагылдырат.","ru":"Точно! Это макроскопическое наблюдение напрямую отражает молекулярный механизм процесса."}},{"id":"b","text":{"en":"The glass beaker itself chemically dissolves into the aqueous solution at room temperature.","ky":"Бөлмө температурасында лабораториялык айнек стакан эритмеде толук эрип кетет.","ru":"Боросиликатное стекло стакана полностью растворяется в воде при комнатной температуре."},"isCorrect":false,"misconceptionTag":"inert_apparatus_confusion","misconceptionLabel":{"en":"Confusing inert borosilicate glassware with active chemical reactants","ky":"Инерттүү лабораториялык идишти активдүү реактив менен алмаштыруу","ru":"Смешение роли инертной химической посуды и реагирующих веществ"},"explanation":{"en":"Borosilicate laboratory glassware is chemically inert under these conditions; only the reagents inside react.","ky":"Лабораториялык боросиликат айнеги бул шарттарда химиялык жактан инерттүү болот.","ru":"Лабораторная посуда из боросиликатного стекла химически инертна в условиях данного опыта."}}]}]'::jsonb),
('electrolysis-copper-chloride-ki-starch','electrochemistry','[{"id":"q1","conceptTag":"electrochemistry","hint":{"en":"Focus on the reactants and products shown in the balanced equation for Electrochemistry.","ky":"«Электрохимия» темасындагы реакциянын баштапкы заттарына жана продуктыларына көңүл буруңуз.","ru":"Обратите внимание на исходные вещества и продукты в уравнении реакции по теме «Электрохимия»."},"prompt":{"en":"Which equation or relationship represents the core chemical principle demonstrated in \"Color-Coded Electrolysis of Potassium Iodide in a U-Tube\"?","ky":"«U-түрүндөгү түтүктө калий иодидинин түстүү электролизи» тажрыйбасындагы негизги процессти кайсы теңдеме же байланыш туюндурат?","ru":"Какая запись отражает ключевой процесс в эксперименте «Наглядный электролиз раствора иодида калия в U-образной трубке»?"},"options":[{"id":"a","text":{"en":"2I⁻ (aq, anode) → I₂ (aq, brown) + 2e⁻  |  2H₂O + 2e⁻ (cathode) → H₂ (g) + 2OH⁻ (pink)","ky":"2I⁻ (aq, anode) → I₂ (aq, brown) + 2e⁻  |  2H₂O + 2e⁻ (cathode) → H₂ (g) + 2OH⁻ (pink)","ru":"2I⁻ (aq, anode) → I₂ (aq, brown) + 2e⁻  |  2H₂O + 2e⁻ (cathode) → H₂ (g) + 2OH⁻ (pink)"},"isCorrect":true,"explanation":{"en":"Correct! This balanced representation accounts for the observed macroscopic change in the experiment.","ky":"Туура! Бул теңдеме тажрыйбада байкалган өзгөрүүнү так сүрөттөйт.","ru":"Верно! Эта схема точно описывает наблюдаемые в опыте изменения."}},{"id":"b","text":{"en":"No chemical or physical interaction occurs between the components.","ky":"Компоненттердин ортосунда эч кандай химиялык же физикалык кубулуш жүрбөйт.","ru":"Между компонентами системы не происходит никаких превращений."},"isCorrect":false,"misconceptionTag":"ignoring_macroscopic_reaction_evidence","misconceptionLabel":{"en":"Overlooking visible evidence of chemical or phase change","ky":"Химиялык же фазалык өзгөрүүнүн визуалдык белгилерин эске албоо","ru":"Игнорирование видимых признаков химического или фазового превращения"},"explana